BEGIN;

-- Ficha de Niní Cáffaro.
--
-- Corrige a sus biografías de origen común (adiascar, copiada por Wikipedia,
-- Color Visión y El Blog del Bolero):
--  * 1969: quedó en 7º lugar en el Primer Festival de la Canción Latina en el
--    Mundo (hoja del sencillo y capítulos de la grabación del festival), no
--    primero ni "medalla de oro".
--  * Primera grabación en 1961 (Funglode, Wikipedia y la entrevista de 2025),
--    no 1962.
--
-- Nuevo premio "Festival de la Canción Dominicana" (AMUCABA, 1968): no hay
-- equivalente en awards; se registra solo el primer lugar de 1968.
-- El tercer lugar de la OTI 1973 no se registra: es una posición en concurso,
-- no un premio, y artist_awards no tiene cómo expresarlo.
--
-- Fuera: esposa e hijos; la anécdota de «Violeta» y los presos del 14 de Junio
-- (una sola familia de fuentes).

INSERT INTO awards (name, organization, country, description)
SELECT 'Festival de la Canción Dominicana', 'AMUCABA', 'República Dominicana',
       'Festival de canción popular organizado por la Asociación de Músicos, Cantantes y Bailarines; primera edición del 19 al 21 de noviembre de 1968 en el Conservatorio Nacional de Música'
 WHERE NOT EXISTS (SELECT 1 FROM awards WHERE name = 'Festival de la Canción Dominicana');
INSERT INTO award_categories (award_id, name)
SELECT a.id, 'Primer lugar' FROM awards a WHERE a.name = 'Festival de la Canción Dominicana'
   AND NOT EXISTS (SELECT 1 FROM award_categories c WHERE c.award_id = a.id AND c.name = 'Primer lugar');

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 1968, 'Por amor', true, 'festivalescancionpopular.blogspot.com (clasificación final y LP de Amucaba) y Diccionario Cultural Dominicano (Funglode); coincide con la ficha de Rafael Solano'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'nini-caffaro' AND a.name = 'Festival de la Canción Dominicana' AND cat.name = 'Primer lugar'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 1968);
INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2020, NULL, true, 'El Caribe (16 jun 2021) y tabla de El Gran Soberano en Wikipedia (es); entregado el 15 jun 2021 en la doble gala 2019-2020. Diario Libre (15 jun 2021) invierte los años con Romeo Santos'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'nini-caffaro' AND a.name = 'Premios Soberano' AND cat.name = 'El Gran Soberano'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2020);

